    words = sentence.split()
    max_len = 0
    for word in words:
        if len(word) % 2 == 0:
            max_len = max(max_len, len(word))
    if max_len == 0:
        return "-1"
    else:
        return max_len

def find_Max_Len_Even(sentence):
    words = sentence.split()
    max_len_even_word = ""
    for word in words:
        if len(word) % 2 == 0:
            if len(word) > len(max_len_even_word):
                max_len_even_word = word
    return max_len_even_word if max_len_even_word else "-1"
